#[cfg(feature = "minio")]
#[test]
fn sealed_lifecycle_rule_filter() {
    let value = super::debug::sample_lifecycle_rule_filter();
    let clone = value.clone();
    assert!(clone == value, "LifecycleRuleFilter: a clone must compare equal");
    let mut other = value.clone();
    other.and = None;
    assert!(value != other, "LifecycleRuleFilter: the and field takes part in PartialEq");
    let mut other = value.clone();
    other.object_size_greater_than = None;
    assert!(
        value != other,
        "LifecycleRuleFilter: the object_size_greater_than field takes part in PartialEq"
    );
    let mut other = value.clone();
    other.object_size_less_than = None;
    assert!(
        value != other,
        "LifecycleRuleFilter: the object_size_less_than field takes part in PartialEq"
    );
    let mut other = value.clone();
    other.prefix = None;
    assert!(value != other, "LifecycleRuleFilter: the prefix field takes part in PartialEq");
    let mut other = value.clone();
    other.tag = None;
    assert!(value != other, "LifecycleRuleFilter: the tag field takes part in PartialEq");
    let mut bare = value.clone();
    bare.and = None;
    bare.object_size_greater_than = None;
    bare.object_size_less_than = None;
    bare.prefix = None;
    bare.tag = None;
    assert!(
        bare.test_tags(&std::collections::HashMap::new()),
        "LifecycleRuleFilter: a filter without tags accepts an untagged object"
    );
    assert!(
        !value.test_tags(&std::collections::HashMap::new()),
        "LifecycleRuleFilter: an untagged object fails a tag constraint"
    );
}

#[cfg(feature = "minio")]
#[test]
fn sealed_replication_rule_filter() {
    let value = super::debug::sample_replication_rule_filter();
    let clone = value.clone();
    assert!(clone == value, "ReplicationRuleFilter: a clone must compare equal");
    let mut other = value.clone();
    other.and = None;
    assert!(value != other, "ReplicationRuleFilter: the and field takes part in PartialEq");
    let mut other = value.clone();
    other.prefix = None;
    assert!(value != other, "ReplicationRuleFilter: the prefix field takes part in PartialEq");
    let mut other = value.clone();
    other.tag = None;
    assert!(value != other, "ReplicationRuleFilter: the tag field takes part in PartialEq");
    let mut bare = value.clone();
    bare.and = None;
    bare.prefix = None;
    bare.tag = None;
    assert!(
        bare.test_tags(&std::collections::HashMap::new()),
        "ReplicationRuleFilter: a filter without tags accepts an untagged object"
    );
    assert!(
        !value.test_tags(&std::collections::HashMap::new()),
        "ReplicationRuleFilter: an untagged object fails a tag constraint"
    );
}

#[cfg(feature = "minio")]
#[test]
fn cached_tags_is_a_cache() {
    let tags = s3s::dto::CachedTags::default();
    let clone = tags.clone();
    assert!(clone == tags, "a cache compares equal regardless of its contents");
    assert_eq!(serde_json::to_string(&tags).expect("serialize a cache"), "{}");
    let parsed: s3s::dto::CachedTags = serde_json::from_str("{\"key\":\"value\"}").expect("deserialize a cache");
    assert!(parsed == tags, "a cache deserializes to an empty cache");
    let mut reset = tags.clone();
    reset.reset();
}

